(async function(){'use strict';
const E=window.LostCargo,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,tab='play',storageOK=true,blocked=false,busy=false,toastTimer,modalAction=null,lastInput=-Infinity;
let initialSeed=(()=>{try{return crypto.getRandomValues(new Uint32Array(1))[0];}catch{return Date.now()>>>0;}})();
const controller=await window.SalvageStore.open(initialSeed);state=controller.state;storageOK=controller.persisted;blocked=controller.blocked||!controller.readable;const raw=!controller.created;let inputRevision=controller.revision,lastCommand=-Infinity;
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2800);}
function active(){return ['route','event','result'].includes(state.phase);}
function button(label,action,cls='',disabled=false){disabled=disabled||(!storageOK&&(['depart','fuel','repair','aid','sellAll','continue','abort'].includes(action)||/^(pay|buy-|feedback-)/.test(action)));return `<button class="${cls}" data-rev="${controller.revision}" data-act="${action}" ${disabled?'disabled':''}>${label}</button>`;}
function picture(type='port',caption=''){let image=type==='port'?'port':type==='station'?'harbor':['wreck','route','anomaly','cabin'].includes(type)?'wreck':null;return `<div class="hero ${type==='port'?'':'short'}">${image&&ART[image]?`<img src="${ART[image]}" alt="${type==='port'?'停靠在港口的旧飞船':type==='wreck'?'静默的空间残骸':'轨道港口'}">`:spaceArt(type)}${(!image||!ART[image])&&ART.ship?`<img class="salvage-ship" src="${ART.ship}" alt="失物号民用飞船">`:''}${caption?`<div class="caption">${caption}</div>`:''}</div>`;}
function spaceArt(kind){return `<svg class="hero-svg" viewBox="0 0 420 190" xmlns="http://www.w3.org/2000/svg"><defs><radialGradient id="sky"><stop stop-color="#745a85"/><stop offset="1" stop-color="#26273e"/></radialGradient><linearGradient id="orb"><stop stop-color="#ba8ea9"/><stop offset=".5" stop-color="#665a82"/><stop offset="1" stop-color="#383d60"/></linearGradient></defs><rect width="420" height="190" fill="url(#sky)"/><g fill="#efcaa6" opacity=".8">${Array.from({length:31},(_,i)=>`<rect x="${(i*43+19)%415}" y="${(i*67+9)%187}" width="${i%5===0?3:1.5}" height="${i%5===0?3:1.5}"/>`).join('')}</g><circle cx="320" cy="75" r="62" fill="url(#orb)"/><path d="M263 66q55 25 113-5M263 97q66 21 108-3" fill="none" stroke="#b29abb" stroke-width="6" opacity=".4"/>${ART.ship?'':`<g transform="translate(95 80)"><path d="M0 25L24 8H88L107 31L93 47H15Z" fill="#a9a1b6" stroke="#3a304c" stroke-width="4"/><path d="M45 9L56 0H75L83 9" fill="#94869f" stroke="#392e48" stroke-width="4"/><path d="M20 22H41V34H12ZM49 21H63V34H49ZM69 21H83V34H69Z" fill="#8eb5cc"/><path d="M37 45L31 58H75L81 45" fill="#d2b8a4" stroke="#3a304c" stroke-width="3"/><rect x="90" y="28" width="17" height="8" fill="#d69a7e"/><path d="M0 28L-22 33L0 38" fill="#92cfe5"/></g>`}<path d="M28 153Q180 125 255 160" stroke="#c9ab87" opacity=".6" stroke-dasharray="3 8" fill="none"/></svg>`;}
function reserveBox(){return `<div class="reserve"><div class="row"><span>现在回港需 <b class="num">${E.homeCost(state)}</b> 燃料</span><span>探索余油 <b class="num">${E.spare(state)}</b></span></div><p class="note" style="margin-bottom:0">越深入，前进与返航都更费油。加油不会缩短已走距离。</p></div>`;}
function port(){const fuel=E.portQuote(state,'buyFuel'),repair=E.portQuote(state,'repair');let debt=12000-state.debt;return `<div class="section-head"><div><div class="eyebrow">LOST CARGO / HOME PORT</div><h1>望潮港</h1></div><span class="tag">第${state.runNo+1}趟准备</span></div><section class="panel"><div class="debt"><div><small>剩余船款</small><div class="badge">没有利息 · 没有离线罚款</div></div><b class="num">${state.debt.toLocaleString()}</b></div><div class="bar"><i style="width:${debt/120}%"></i></div><p class="note" style="margin-bottom:0">已还 ${debt.toLocaleString()} / 12,000。第一步：平安带回一趟收获。</p></section>${picture('port','失物号 · 二手民用接驳船<small>船不新了，远处还有新的东西。</small>')}${button('出发 · 废环回收线 →','depart','primary full')}<div class="spacer"></div><section class="panel"><h3>本趟委托 · 航区测绘</h3><p class="note">带着记录箱探索至少3处航点，再返回港口。记录箱占1格，不要求走满8站。</p><div class="section-head" style="margin:0"><b style="color:var(--amber)">报酬 180 零件</b><small>安全返港后自动结算</small></div></section><div class="split">${button(`<strong>补充燃料 +${fuel.amount}</strong><small>实付${fuel.cost}零件 · 每点2零件</small>`,'fuel','',!fuel.amount)}${button(`<strong>维修船体 +${repair.amount}</strong><small>实付${repair.cost}零件 · 每点2零件</small>`,'repair','',!repair.amount)}</div><p class="note">最多8站。返航由你决定；不要求在线等计时。剩余油量、船况与收入会延续到下一趟。</p><div class="split">${button('改装设备','tools','ghost')}${button('偿还船款','repay','ghost')}</div>${state.cargo.length?`<div class="spacer"></div>${button('货舱还有 '+E.used(state)+' 格货物 · 查看／出售','cargo','full')}`:''}${E.preparation(state).needsAid?`<div class="spacer"></div>${button('码头短工 · 获取基本补给','aid','full')}<p class="note">保底救助，不加船债、不需要广告。</p>`:''}`;}
function route(){return `<div class="section-head"><div><div class="eyebrow">WRECK-RING RECOVERY</div><h1>选择下一站</h1></div><span class="tag">已走 ${state.depth} / 8</span></div>${picture('route')}<div class="track">${Array.from({length:8},(_,i)=>`<span class="${i<state.depth?'done':i===state.depth?'now':''}"></span>`).join('')}</div>${reserveBox()}${state.depth<3?`<p class="note">委托进度 ${state.depth}/3 · 记录箱${state.run.contractActive?'仍在货舱':'已放弃，本趟不再结算委托报酬'}</p>`:`<p class="note">${state.run.contractActive?'委托记录已够，返港可领取180零件。':'委托已放弃，其他货物仍可带回。'}</p>`}${state.depth>=8?'<div class="panel"><h2>本趟航区已到边缘</h2><p class="note">安全带回收获，本身就是一次成功。回港后可以开启新航次。</p></div>':state.route.map(r=>{const q=E.quote(state,r);return `<button class="route-card" data-travel="${esc(r.uid)}" ${q.enabled?'':'disabled'}><div class="head"><strong>${esc(r.name)}</strong><span class="tag">风险 ${esc(r.risk)}</span></div><span class="signal">${esc(r.signal)} · 第${r.depth}航点</span><div class="forecast"><span>前进耗油<b class="num">${q.out}</b></span><span>抵达后返航<b class="num">${q.returnCost}</b></span><span>预留后可用余油<b class="num">${q.free}</b></span></div><small class="arrival">抵达后剩余 ${q.arrival} 燃料</small>${q.enabled?'':`<p class="note">油量不足：需要至少${q.out+q.returnCost}，现有${state.fuel}</p>`}</button>`;}).join('')}<div class="spacer"></div>${state.depth?button(`现在返航 · 消耗${E.homeCost(state)}燃料 →`,'home','primary full',state.fuel<E.homeCost(state)):button('取消本次出发，回港准备','abort','full ghost')}<p class="note">路线和事件会保存，刷新不会重抽。返航只扣油，不自动卖货、修船或还债。</p>${state.depth&&(state.hull===0||state.fuel<E.homeCost(state))?button('呼叫普通拖航救援','rescue','full ghost'):''}`;}
function event(){const ev=E.encounter(state);return `<div class="section-head"><div><div class="eyebrow">ENCOUNTER / ${String(state.depth).padStart(2,'0')}</div><h1>探索现场</h1></div><span class="tag">当前返航 ${E.homeCost(state)} 油</span></div>${picture(ev.kind)}<section class="panel"><div class="event-label">◇ 第${state.depth}处发现</div><h2>${esc(ev.title)}</h2><p class="lead" style="margin-top:12px">${esc(ev.text)}</p></section><p class="note">选择会立即结算。货舱满时可以先整理；放弃也算一个选择。</p>${ev.choices.map((c,i)=>{const err=E.checkChoice(state,c);return `<button class="choice " data-choice="${c.id}" data-nonce="${esc(ev.nonce)}" ${err?'disabled':''}><strong>${esc(c.label)} <span style="float:right">›</span></strong><small>${esc(c.desc)}</small>${c.effect.fuel>100-state.fuel?`<small>储量上限：实际增加${100-state.fuel}燃料</small>`:''}${c.effect.hull>100-state.hull?`<small>船体上限：实际恢复${100-state.hull}耐久</small>`:''}${(c.risk?.[1]||-(c.effect.hull||0))>=state.hull?'<small>注意：可能需要拖航救援</small>':''}${err?`<small>○ ${esc(err)}</small>`:''}</button>`;}).join('')}${reserveBox()}<div class="split">${button('整理货舱','cargo','ghost')}${button('放弃现场并返航','home','ghost')}</div>`;}
function result(){const r=state.result;return `<div class="eyebrow">CHOICE RECORDED</div><section class="panel" style="margin-top:15px"><div class="result-mark">✓</div><h2 style="text-align:center">${esc(r.title)}</h2><p class="lead" style="margin-top:18px">${esc(r.text)}</p><div class="changes">${r.changes.length?r.changes.map(x=>`<span>${esc(x)}</span>`).join(''):'<span>资源未变化</span>'}</div></section>${reserveBox()}${button(state.depth>=8?'查看返航路线 →':'继续查看航路 →','continue','primary full')}<div class="spacer"></div>${button(`见好就收 · 返航需${E.homeCost(state)}燃料`,'home','full ghost')}`;}
function summary(){const r=E.summaryView(state);return `<div class="eyebrow">VOYAGE ${String(r.run).padStart(2,'0')} / RETURN</div><h1>${r.rescue?'已被拖回港口':'平安归航'}</h1>${picture('port')}<div class="stats-grid"><div><b>${r.depth}</b><small>探索航点</small></div><div><b>${r.returnFuel}</b><small>实际返航耗油</small></div><div><b>${E.cargoValue(state)}</b><small>尚未出售货值</small></div></div><section class="panel"><h3>本趟账目</h3><div class="spacer"></div><div class="ledger"><span>途中收入（非售货）</span><b class="positive">+${r.eventIncome}</b><span>委托结算</span><b class="positive">+${r.reward}</b><span>途中服务支出</span><b class="negative">−${r.spent}</b>${r.rescue?`<span>拖航实付</span><b class="negative">−${r.rescueFee}</b>`:''}<span>本趟新货已售</span><b class="positive">+${r.salesCurrent}</b><span>跨趟旧货已售</span><b class="positive">+${r.salesCarried}</b><span>港口油料／维修</span><b class="negative">−${r.supplySpent+r.repairSpent}</b><span>设备／还款</span><b class="negative">−${r.toolSpent+r.debtPaid}</b><span>新收获已实现收支</span><b>${r.operatingNet}</b><span class="total">现金实际变动</span><b class="total">${r.cashDelta>=0?'+':''}${r.cashDelta}</b></div><p class="note">${r.legacy?'旧版历史明细不能完整追溯，余额保留；以下仅计升级后的操作。':''}此项不含旧货、设备和还款，也不预扣未做的补给。油料和耐久尚未补满。未售货物不算现金；补给、维修、还债由你主动决定。</p></section>${r.rescue?`<p class="note">${r.lost}件本趟货物抵扣了救援成本。已发现的见闻保留，不增加船债。</p>`:''}${E.cargoValue(state)?button('出售回收货 · 获得'+E.cargoValue(state)+'零件','sellAll','primary full'):''}<div class="spacer"></div><div class="split">${button('先看看货舱','cargo','ghost')}${button('返回港口准备 →','port','primary')}</div><details class="feedback"><summary>本趟主要体验如何？（可不填）</summary><p class="note">只记在本机，不影响结果。</p><div class="split">${button('平稳','feedback-steady')}${button('紧张','feedback-tense')}${button('有些没看懂','feedback-unclear')}${button('暂不回答','feedback-skip')}</div></details>`;}
function cargo(){return `<div class="section-head"><div><div class="eyebrow">CARGO / CAPACITY</div><h1>船上的东西</h1></div><span class="tag">${E.used(state)} / ${state.capacity}格</span></div><p class="note">空间有限，不必带走所有东西。放弃已经拿到的货物不会退还处理费用。</p><section class="panel">${state.cargo.length?state.cargo.map(x=>`<div class="cargo-item"><div class="symbol">${x.contract?'▤':'◇'}</div><div class="text"><strong>${esc(x.name)}</strong><small>${x.size}格 · ${x.contract?'委托用品，返港结算':`港口可售 ${x.value} 零件`}</small>${x.ability?'<small>可消耗以恢复22耐久</small>':''}</div><div class="cargo-actions">${!x.contract&&!active()?`<button data-sell="${x.uid}">出售</button>`:''}${x.ability?`<button data-use="${x.uid}" ${state.hull===100?'disabled':''}>使用</button>`:''}${active()?`<button data-discard="${x.uid}" class="danger">放弃</button>`:''}</div></div>`).join(''):'<div class="empty">货舱是空的。<br>好消息：还有很多位置。</div>'}</section>${!active()&&E.cargoValue(state)?button(`全部出售 · ${E.cargoValue(state)}零件`,'sellAll','primary full'):''}<div class="spacer"></div>${button(active()?'返回当前航行 →':'回港看看 →','play','full ghost')}`;}
function journal(){return `<div class="section-head"><div><div class="eyebrow">LOCAL FLIGHT LOG</div><h1>航行手记</h1></div><span class="tag">${state.archive.length}件见闻</span></div><p class="note">只记录已经发生的事情。卖掉货物，不会抹掉见闻。</p>${state.archive.length?`<section class="panel"><h3>带上过船的物件</h3><div class="changes">${state.archive.map(x=>`<span>${esc(x.name)}</span>`).join('')}</div></section>`:''}<section class="panel">${state.log.length?[...state.log].reverse().slice(0,40).map(x=>`<div class="log-item"><small>第${x.run}趟 · ${x.depth?`航点${x.depth}`:'港口'}</small>${esc(x.text)}</div>`).join(''):'<div class="empty">下一页，等你自己填写。</div>'}</section>`;}
function render(resetScroll=false){const health=$('#storage-warning');health.hidden=storageOK&&!blocked;if(!health.hidden)health.textContent=blocked?'档案校验失败，原数据保留。当前只读，请导出原始备份或导入有效存档。':'保存不可用，操作不会提交。请导出当前档案或在设置中重试。';$('#resources').innerHTML=[['燃料','◈',state.fuel+'/100',state.fuel<=E.homeCost(state)+8&&active()],['耐久','⬡',state.hull+'/100',state.hull<30],['零件','◎',state.money.toLocaleString(),false],['货舱','▣',E.used(state)+'/'+state.capacity,E.used(state)===state.capacity]].map(([a,icon,b,low])=>`<div class="resource ${low?'low':''}"><span>${icon} ${a}</span><b class="num">${b}</b></div>`).join('');const body=tab==='cargo'?cargo():tab==='journal'?journal():state.phase==='port'?port():state.phase==='route'?route():state.phase==='event'?event():state.phase==='result'?result():summary();$('#main').innerHTML='<div class="reveal">'+(blocked?'<section class="panel"><h2>档案暂未接通</h2><p>原数据保留，请打开设置处理。</p></section>':body)+`</div><div class="footer-note">开发自测 ${E.VERSION} · ${(window.LostCargoBuild?.commit||'dev').slice(0,7)} · ${storageOK?'已保存':'未保存'}<br>没有广告 · 没有真实支付</div>`;$('#nav').innerHTML=[['play','⌂',active()?'航行':'港口'],['route','⌁','航路'],['cargo','▣','货舱'],['journal','▤','航记']].map(([id,ic,t])=>`<button data-tab="${id}" class="${tab===id?'active':''}"><span>${ic}</span>${t}</button>`).join('');if(!storageOK||blocked)$('#main').querySelectorAll('[data-travel],[data-choice],[data-sell],[data-use],[data-discard]').forEach(b=>b.disabled=true);$('#main').querySelectorAll('button').forEach(b=>b.dataset.rev=String(controller.revision));if(blocked)$('#resources').querySelectorAll('b').forEach(b=>b.textContent='—');if(resetScroll)window.scrollTo({top:0,behavior:'auto'});}
async function act(action,expected=inputRevision){if(busy||!storageOK||blocked)return toast('当前不能提交，请先在设置中处理保存');if(performance.now()-lastCommand<450)return;lastCommand=performance.now();busy=true;let r;try{r=await controller.act(action,expected);state=controller.state;storageOK=controller.persisted;blocked=controller.blocked||!controller.readable;if(!r.ok)toast(r.message);else tab='play';}finally{busy=false;render(!!r?.ok);}return r;}
async function replaceState(value,expected){if(busy)return;busy=true;try{const r=await controller.replace(value,expected);if(!r.ok)toast(r.message);else{tab='play';close();}}finally{busy=false;state=controller.state;storageOK=controller.persisted;blocked=controller.blocked||!controller.readable;render(true);}}
function modal(title,html,confirmLabel,action){if($('#overlay').hidden&&!history.state?.salvageModal)history.pushState({salvageModal:true},'');modalAction=action;$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal-buttons').innerHTML=confirmLabel?button('暂不操作','close','ghost')+button(esc(confirmLabel),'confirm','primary'):button('知道了','close','primary');$('#overlay').hidden=false;$('#modal-close').focus();}
function close(fromPop=false){modalAction=null;$('#overlay').hidden=true;if(!fromPop&&history.state?.salvageModal)history.back();}
function tools(){modal('港口改装',`<p>工具不是纯数值加速，它们能在部分遭遇中提供新的处理办法。只在港口购买，之后一直保留。</p><div class="panel"><h3>扫描仪 · 240零件</h3><p>帮助识别某些异常和回收方式。</p>${button(state.tools.includes('scanner')?'已安装':'安装扫描仪','buy-scanner','full primary',state.tools.includes('scanner')||state.money<240)}</div><div class="panel"><h3>牵引绞盘 · 280零件</h3><p>部分重型回收可以减少损伤或占用。</p>${button(state.tools.includes('winch')?'已安装':'安装牵引绞盘','buy-winch','full primary',state.tools.includes('winch')||state.money<280)}</div>`);}
function repay(){modal('偿还船款',`<p>还款由你主动决定，不会把本趟利润自动扣走。至少保留50零件作下次补给。</p><h2 class="num">剩余 ${state.debt.toLocaleString()}</h2><div class="spacer"></div><div class="split">${button('归还100','pay100','primary',state.money<Math.min(100,state.debt)+50||!state.debt)}${button('归还500','pay500','primary',state.money<Math.min(500,state.debt)+50||!state.debt)}</div>`);}
function settings(){modal('规则与存档',`<div class="help-rule"><b>你的目标</b><p>开着二手船跑航线，把收获带回港口，慢慢还清12,000零件船款。没有时限、利息、挂机罚款。</p></div><div class="help-rule"><b>油耗会随深入增加</b><p>每站前进费用逐步提高。返航油耗 = 3 + 已走航线距离的一半（向上取整）。距离使用各次航行实际耗油记录，加油不会减少它。第1～8站的基础前进油耗为${E.LEG.join('、')}，支线另有少量差别。</p></div><div class="help-rule"><b>保持可返航</b><p>选择下一站前，必须有足够油抵达并预留新的返航费用。事件使用探索余油，不动返航储备。船体仍然可能损坏，请看清选择上的代价。</p></div><div class="help-rule"><b>不必走完8站</b><p>探索3站即可满足本趟测绘委托。早回来不是失败。全程没有强制倒计时；离线时不会偷偷损耗资源。</p></div><div class="help-rule"><b>保存方式</b><p>只保存到本浏览器的独立本地存档，刷新继续。文件移动、更换浏览器或清理数据可能使存档不可见，请导出备份。与旧版《失物星球》完全隔离。</p></div><div class="split" style="margin-top:15px">${button('导出存档','export','primary')}${button('导入存档','import')}</div><div class="spacer"></div>${button('导出试玩反馈（不含未遇事件）','report','full')}<div class="spacer"></div>${button('重试保存','retry','full')}<p class="note">无联网、无广告SDK、无真实付款。当前使用开发后备画面，美术仍待审核。</p>`);}
function download(name,data){const b=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function action(name){if(name==='close'){close();return;}if(name==='confirm'){const f=modalAction;close();f?.();return;}if(name==='settings'){settings();return;}if(name==='cargo'||name==='journal'||name==='play'){tab=name;render(true);return;}if(name==='route'){tab='play';render(true);return;}if(name==='home'){modal('现在返航？',`<p>消耗 <b>${E.homeCost(state)} 燃料</b>，带回当前货物。${state.phase==='event'?'当前未处理的现场将放弃。':''}</p><p>不会自动卖货、维修或偿还船款。</p>`,'确认返航',()=>act({type:'return'}));return;}if(name==='rescue'){modal('呼叫普通救援',`<p>本趟货物抵扣拖航费用，现金最多再扣50零件。带回基本油料与可航行船体；已发现见闻保留，不增加债务。</p>`,'接受救援',()=>act({type:'rescue'}));return;}if(name==='tools'){tools();return;}if(name==='repay'){repay();return;}if(name==='export'){download('lostcargo-save-'+Date.now()+'.json',controller.export());return;}if(name==='report'){download('lostcargo-feedback-'+Date.now()+'.json',{version:E.VERSION,runNo:state.runNo,fuel:state.fuel,hull:state.hull,money:state.money,debt:state.debt,summary:E.summaryView(state),log:state.log,decisions:state.telemetry,ledger:state.ledger});return;}if(name==='import'){$('#import-file').click();return;}if(name==='retry'){void controller.retry();close();return;}if(name==='reset'){modal('只重开这个Demo',`<p>先导出备份。此操作只删除本Demo的测试进度，不接触旧版游戏。将从120零件、60燃料、100耐久开始，航路重新生成。</p>`,'确认重开',()=>{void replaceState(E.create(Date.now()>>>0),inputRevision);});return;}if(name.startsWith('feedback-')){act({type:'feedback',answer:name.slice(9)}).then(()=>toast('已记在本地，感谢。'));return;}if(name.startsWith('buy-')){close();act({type:'tool',id:name.slice(4)});return;}if(name.startsWith('pay')){close();act({type:'repay',amount:Number(name.slice(3))});return;}const map={fuel:'buyFuel',repair:'repair',depart:'depart',continue:'continue',port:'port',abort:'abort',aid:'aid',sellAll:'sellAll'};if(map[name])act({type:map[name]});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;inputRevision=Number(b.dataset.rev??controller.revision);const a=b.dataset.act||'';if(b.dataset.tab){tab=b.dataset.tab==='route'?'play':b.dataset.tab;render(true);return;}if(a){action(a);return;}const now=performance.now();if(now-lastInput<350)return;lastInput=now;if(b.dataset.travel)act({type:'travel',id:b.dataset.travel});else if(b.dataset.choice)act({type:'choose',id:b.dataset.choice,nonce:b.dataset.nonce});else if(b.dataset.sell)act({type:'sell',id:+b.dataset.sell});else if(b.dataset.use)act({type:'use',id:+b.dataset.use});else if(b.dataset.discard){const x=state.cargo.find(x=>x.uid===+b.dataset.discard);modal('放弃这件货物？',`<p>${esc(x?.name)}将离开货舱，不获得零件。${x?.contract?'放弃记录箱也会失去本趟180零件委托报酬。':''}</p>`,'确认放弃',()=>act({type:'discard',id:+b.dataset.discard}));}});
$('#modal-close').onclick=close;$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))close();});document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&!$('#overlay').hidden){const els=[...$('#overlay').querySelectorAll('button:not(:disabled),input')],first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('文件过大');const s=E.restore(await f.text());modal('使用导入存档？',`<p>将替换本Demo当前进度。第${s.runNo}趟，剩余船款${s.debt}。建议先导出当前备份。</p>`,'确认导入',()=>{void replaceState(s,inputRevision);});}catch(err){toast('导入失败，原档未动：'+err.message);}e.target.value='';});
controller.subscribe(()=>{const previous=state.revision;state=controller.state;storageOK=controller.persisted;blocked=controller.blocked||!controller.readable;if(!busy&&state.revision!==previous)close();render();});
window.addEventListener('popstate',()=>close(true));
window.__SALVAGE__={state:()=>E.restore(state),status:()=>({revision:controller.revision,persisted:controller.persisted,blocked:controller.blocked,error:controller.error}),build:window.LostCargoBuild,ready:()=>!busy&&performance.now()-lastCommand>=450};

render();
if(!raw&&!blocked&&storageOK)modal('欢迎登船，船长',`<div class="eyebrow">失物号：星海拾荒 · 首航Demo</div><p>你赊来一艘旧民航接驳船，欠下12,000零件。卖家说它九成新，剩下一成是保修。</p><p>先完成一趟回收：选择航点、处理遇见的事，把收获带回港口。走得越远，前进和返航都更费油。</p><p>每趟最多8站；随时可以收手。没有广告，也不会在你离开时替你做危险决定。</p><p class="note">新档：燃料60／耐久100／零件120／货舱4格。途中内容不预先揭示。</p>`);
})();
